SELECT "t3"."line_id", "t3"."obligation_id", "t3"."kind", "t3"."due", 'goods_overdue' AS "route", 'open_obligations' AS "context"
FROM (SELECT "t1"."line_id", "obligation"."id" AS "obligation_id", "obligation"."kind", "obligation"."due"
        FROM (SELECT "line_id", "request_number", "item", "quantity", "way", "customer0" AS "customer"
                FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                        FROM "return_request_line"
                            INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                WHERE "t"."state" IN ('goods_received', 'settling')) AS "t1"
            INNER JOIN "obligation" ON "obligation"."entity" = 'return_request_line' AND "obligation"."key" = CAST("t1"."line_id" AS VARCHAR)
        WHERE "obligation"."kind" IN ('credit_note', 'payment', 'replacement') AND "obligation"."state" IN ('open', 'overdue', 'reopened')) AS "t3"
    INNER JOIN (SELECT "line_id"
        FROM (SELECT "t13"."line_id", "t13"."request_number", "t13"."item", "t13"."quantity", "t13"."way", "t13"."customer", "t13"."credit_note_id", "t13"."issued_date", "t13"."payment_id", "t13"."paid_date", "t13"."shipment_id", "t13"."shipped_date", "t30"."max_late", "t30"."kinds_open"
                FROM (SELECT "t6"."line_id", "t6"."request_number", "t6"."item", "t6"."quantity", "t6"."way", "t6"."customer", "t12"."credit_note_id", "t12"."issued_date", "t12"."payment_id", "t12"."paid_date", "t12"."shipment_id", "t12"."shipped_date"
                        FROM (SELECT "line_id", "request_number", "item", "quantity", "way", "customer0" AS "customer"
                                FROM (SELECT "return_request_line0"."line_id", "return_request_line0"."request_number", "return_request_line0"."line_no", "return_request_line0"."item", "return_request_line0"."quantity", "return_request_line0"."unit_price", "return_request_line0"."reason", "return_request_line0"."requested_resolution", "return_request_line0"."requested_variant", "return_request_line0"."state", "return_request_line0"."way", "return_request_line0"."customer", "return_request0"."customer" AS "customer0", "return_request0"."order_number", "return_request0"."channel", "return_request0"."requested_date", "return_request0"."state" AS "state0"
                                        FROM "return_request_line" AS "return_request_line0"
                                            INNER JOIN "return_request" AS "return_request0" ON "return_request_line0"."request_number" = "return_request0"."request_number") AS "t4"
                                WHERE "t4"."state" IN ('goods_received', 'settling')) AS "t6"
                            LEFT JOIN (SELECT "t11"."line_id", "t11"."credit_note_id", "t11"."issued_date", "t11"."payment_id", "t11"."paid_date", "replacement_shipment"."shipment_id", "replacement_shipment"."shipped_date"
                                FROM (SELECT "t10"."line_id", "t10"."request_number", "t10"."item", "t10"."quantity", "t10"."way", "t10"."customer", "t10"."credit_note_id", "t10"."customer0", "t10"."issued_date", "t10"."amount", "t10"."status", "refund_payment"."payment_id", "refund_payment"."paid_date", "refund_payment"."amount" AS "amount0"
                                        FROM (SELECT "t9"."line_id", "t9"."request_number", "t9"."item", "t9"."quantity", "t9"."way", "t9"."customer", "credit_note"."credit_note_id", "credit_note"."customer" AS "customer0", "credit_note"."issued_date", "credit_note"."amount", "credit_note"."status"
                                                FROM (SELECT "line_id", "request_number", "item", "quantity", "way", "customer0" AS "customer"
                                                        FROM (SELECT "return_request_line1"."line_id", "return_request_line1"."request_number", "return_request_line1"."line_no", "return_request_line1"."item", "return_request_line1"."quantity", "return_request_line1"."unit_price", "return_request_line1"."reason", "return_request_line1"."requested_resolution", "return_request_line1"."requested_variant", "return_request_line1"."state", "return_request_line1"."way", "return_request_line1"."customer", "return_request1"."customer" AS "customer0", "return_request1"."order_number", "return_request1"."channel", "return_request1"."requested_date", "return_request1"."state" AS "state0"
                                                                FROM "return_request_line" AS "return_request_line1"
                                                                    INNER JOIN "return_request" AS "return_request1" ON "return_request_line1"."request_number" = "return_request1"."request_number") AS "t7"
                                                        WHERE "t7"."state" IN ('goods_received', 'settling')) AS "t9"
                                                    LEFT JOIN "credit_note" ON "t9"."line_id" = "credit_note"."line_id") AS "t10"
                                            LEFT JOIN "refund_payment" ON "t10"."credit_note_id" = "refund_payment"."credit_note_id") AS "t11"
                                    LEFT JOIN "replacement_shipment" ON "t11"."line_id" = "replacement_shipment"."line_id") AS "t12" ON "t6"."line_id" = "t12"."line_id") AS "t13"
                    LEFT JOIN (SELECT "t18"."line_id", MAX(CASE WHEN "t18"."due" IS NULL THEN NULL ELSE COALESCE("t28"."_ttrp_n_n20_0", 0) END) AS "max_late", COUNT("t18"."kind") AS "kinds_open"
                        FROM (SELECT "t16"."line_id", "obligation0"."id" AS "obligation_id", "obligation0"."kind", "obligation0"."due"
                                FROM (SELECT "line_id", "request_number", "item", "quantity", "way", "customer0" AS "customer"
                                        FROM (SELECT "return_request_line2"."line_id", "return_request_line2"."request_number", "return_request_line2"."line_no", "return_request_line2"."item", "return_request_line2"."quantity", "return_request_line2"."unit_price", "return_request_line2"."reason", "return_request_line2"."requested_resolution", "return_request_line2"."requested_variant", "return_request_line2"."state", "return_request_line2"."way", "return_request_line2"."customer", "return_request2"."customer" AS "customer0", "return_request2"."order_number", "return_request2"."channel", "return_request2"."requested_date", "return_request2"."state" AS "state0"
                                                FROM "return_request_line" AS "return_request_line2"
                                                    INNER JOIN "return_request" AS "return_request2" ON "return_request_line2"."request_number" = "return_request2"."request_number") AS "t14"
                                        WHERE "t14"."state" IN ('goods_received', 'settling')) AS "t16"
                                    INNER JOIN "obligation" AS "obligation0" ON "obligation0"."entity" = 'return_request_line' AND "obligation0"."key" = CAST("t16"."line_id" AS VARCHAR)
                                WHERE "obligation0"."kind" IN ('credit_note', 'payment', 'replacement') AND "obligation0"."state" IN ('open', 'overdue', 'reopened')) AS "t18"
                            LEFT JOIN (SELECT "t24"."due" AS "_ttrp_k_n20_0_due", COUNT("t26"."_ttrp_d_n20_0") AS "_ttrp_n_n20_0"
                                FROM (SELECT "obligation1"."due"
                                        FROM (SELECT "line_id", "request_number", "item", "quantity", "way", "customer0" AS "customer"
                                                FROM (SELECT "return_request_line3"."line_id", "return_request_line3"."request_number", "return_request_line3"."line_no", "return_request_line3"."item", "return_request_line3"."quantity", "return_request_line3"."unit_price", "return_request_line3"."reason", "return_request_line3"."requested_resolution", "return_request_line3"."requested_variant", "return_request_line3"."state", "return_request_line3"."way", "return_request_line3"."customer", "return_request3"."customer" AS "customer0", "return_request3"."order_number", "return_request3"."channel", "return_request3"."requested_date", "return_request3"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line3"
                                                            INNER JOIN "return_request" AS "return_request3" ON "return_request_line3"."request_number" = "return_request3"."request_number") AS "t19"
                                                WHERE "t19"."state" IN ('goods_received', 'settling')) AS "t21"
                                            INNER JOIN "obligation" AS "obligation1" ON "obligation1"."entity" = 'return_request_line' AND "obligation1"."key" = CAST("t21"."line_id" AS VARCHAR)
                                        WHERE "obligation1"."kind" IN ('credit_note', 'payment', 'replacement') AND "obligation1"."state" IN ('open', 'overdue', 'reopened')
                                        GROUP BY "obligation1"."due") AS "t24"
                                    INNER JOIN (SELECT *
                                        FROM (SELECT "cal_date" AS "_ttrp_d_n20_0", "working_day" AS "_ttrp_w_n20_0"
                                                FROM "date_dim") AS "t25"
                                        WHERE "_ttrp_w_n20_0") AS "t26" ON "t24"."due" < "t26"."_ttrp_d_n20_0" AND "t26"."_ttrp_d_n20_0" <= :as_of
                                GROUP BY "t24"."due") AS "t28" ON "t18"."due" = "t28"."_ttrp_k_n20_0_due"
                        GROUP BY "t18"."line_id") AS "t30" ON "t13"."line_id" = "t30"."line_id") AS "t31"
        WHERE "t31"."way" IN ('exchange', 'replacement_no_return') AND "t31"."shipment_id" IS NULL AND "t31"."max_late" > 0
        GROUP BY "line_id") AS "t34" ON "t3"."line_id" = "t34"."line_id"
